#pragma once

// Catch2's catch_user_config.hpp (regenerated by vcpkg at install time)
// unconditionally re-defines CATCH_CONFIG_CONSOLE_WIDTH to 80, which
// overrides whatever value we pass via target_compile_definitions. Force
// a wide console by including the user config first, then redefining
// the macro before any other Catch2 header (catch_test_macros.hpp pulls
// in catch_console_width.hpp which is the consumer of this value).
#include <catch2/catch_user_config.hpp>
#undef CATCH_CONFIG_CONSOLE_WIDTH
#define CATCH_CONFIG_CONSOLE_WIDTH 200

#include <catch2/catch_test_macros.hpp>
#include <catch2/catch_template_test_macros.hpp>
#include <catch2/generators/catch_generators.hpp>
#include <catch2/benchmark/catch_benchmark.hpp>
#include <libassert/assert-catch2.hpp>

#include "common.h"
#include <string>
#include <ranges>